import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BV21bweQ.js";const f=JSON.parse('{"title":"五大主族总览","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/五大主族总览.md","filePath":"表层/种族/五大主族总览.md","lastUpdated":1787066340000}'),l={name:"表层/种族/五大主族总览.md"};function i(h,a,n,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="五大主族总览" tabindex="-1">五大主族总览 <a class="header-anchor" href="#五大主族总览" aria-label="Permalink to &quot;五大主族总览&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>五大主族为共同体时期的核心五族——牛族、鹿族、鹤族、熊族、甲族，共同体旗帜上的五颗星分别代表这五个种族。但共同体时期的种族不止五个，鸽族、鹰族、狮族等其余多个种族也存在于共同体之中。</p><h2 id="五大主族一览" tabindex="-1">五大主族一览 <a class="header-anchor" href="#五大主族一览" aria-label="Permalink to &quot;五大主族一览&quot;">​</a></h2><h3 id="牛族——农业担当" tabindex="-1">牛族——农业担当 <a class="header-anchor" href="#牛族——农业担当" aria-label="Permalink to &quot;牛族——农业担当&quot;">​</a></h3><p>牛族的种族核心特质是<strong>耐心与求稳</strong>。共同体时期负责农业相关的一切，为整个文明提供粮食基础。黑暗时代中，牛族成为<strong>首个彻底沦为奴隶的种族</strong>，曾试图抵抗新五族的压迫，但被法师以绝对力量镇压至近乎灭绝，剩余族人彻底丧失主权，成为流亡种族。当代牛族隐居，族群规模极小，与兔族、鹤族联系紧密。</p><h3 id="鹿族——科研担当" tabindex="-1">鹿族——科研担当 <a class="header-anchor" href="#鹿族——科研担当" aria-label="Permalink to &quot;鹿族——科研担当&quot;">​</a></h3><p>鹿族的种族核心特质是<strong>好奇心与求知欲</strong>。共同体时期负责科研相关的一切，是五大主族之首。黑暗时代中鹿族沦为法师的助手/宠物，此后重新崛起。当代鹿族为<strong>世界一极</strong>，拥有全大陆最先进的科技水平，当前与熊族处于冷战对峙之中。</p><h3 id="鹤族——政治担当" tabindex="-1">鹤族——政治担当 <a class="header-anchor" href="#鹤族——政治担当" aria-label="Permalink to &quot;鹤族——政治担当&quot;">​</a></h3><p>鹤族的种族核心特质是<strong>总体思考与大局观</strong>。共同体时期负责政治相关的一切，但在神明掌握实权的情况下，仅承担传递神明信息与基层管理工作，严重缺乏顶层策略制定的实践经验，执政威信不足。共同体解体后鹤族隐居山林，族群规模极小。</p><h3 id="熊族——工业担当" tabindex="-1">熊族——工业担当 <a class="header-anchor" href="#熊族——工业担当" aria-label="Permalink to &quot;熊族——工业担当&quot;">​</a></h3><p>熊族的种族核心特质是<strong>建设与发展欲</strong>。共同体时期负责工业相关的一切。共同体末期内斗中熊族被鹿族排挤，此后举族北迁至北境恶劣地带，生活质量长期低下。当代熊族为<strong>世界一极</strong>，拥有全大陆最先进的工业水平，数百年来保持着红色的旗帜与五星的一角作为标志，无比怀念共同体时期，渴望南下光复故土。当前与鹿族冷战对峙。</p><h3 id="甲族——军事担当" tabindex="-1">甲族——军事担当 <a class="header-anchor" href="#甲族——军事担当" aria-label="Permalink to &quot;甲族——军事担当&quot;">​</a></h3><p>甲族的种族核心特质是<strong>服从与执行力</strong>。共同体时期负责军事相关的一切，旧时代国防军几乎全由甲族组成。甲族目前已<strong>近乎灭绝</strong>：灭绝原因无人记载（相关记录被刻意抹除），幸存者以个计数，其中一位长期做客于红星孤儿院。甲族的繁衍与生活习性与其他种族差异极大，过去一度被外界视为&quot;畸形怪种&quot;。</p><h2 id="当代格局" tabindex="-1">当代格局 <a class="header-anchor" href="#当代格局" aria-label="Permalink to &quot;当代格局&quot;">​</a></h2><p>五大主族在当代已分化为两极对峙格局：鹿族与熊族各自成为世界一极，牛族与鹤族隐居山林，甲族近乎灭绝。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>甲族灭绝的具体经过、鹿族在黑暗时代的暗中崛起等真相不属表层认知。</p></blockquote><ul><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./">种族设定索引</a></li><li><a href="./鹿族">鹿族</a></li><li><a href="./熊族">熊族</a></li><li><a href="./牛族">牛族</a></li><li><a href="./鹤族">鹤族</a></li><li><a href="./甲族">甲族</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li></ul><hr>',23)])])}const p=e(l,[["render",i]]);export{f as __pageData,p as default};
